-- Named places (villages and towns) per city, picked as pickup / drop-off on route-based
-- orders (docs/routes/city-places.md). city_key is the city stop key ("city-hebron"), so the
-- places exist independently of the city rows, which the API creates on first admin use.
-- Seeded from apps/api/data/city-places.json (OpenStreetMap place nodes, approximate
-- village-centre positions, plus each city centre). Admins add, edit and disable places in
-- the admin app; rows are never deleted because orders keep the place id.
--
-- Orders also keep the chosen place's id and its names as they were at ordering time.
-- pickup_details / dropoff_details (VARCHAR(300), already there) stay as the optional
-- "more details" text.

CREATE TABLE `city_places` (
    `id` VARCHAR(191) NOT NULL,
    `city_key` VARCHAR(80) NOT NULL,
    `name_ar` VARCHAR(160) NOT NULL,
    `name_en` VARCHAR(160) NOT NULL,
    `latitude` DECIMAL(9, 6) NOT NULL,
    `longitude` DECIMAL(9, 6) NOT NULL,
    `approximate` BOOLEAN NOT NULL DEFAULT true,
    `source` VARCHAR(100) NOT NULL,
    `active` BOOLEAN NOT NULL DEFAULT true,
    `sort_order` INTEGER NOT NULL DEFAULT 0,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,

    INDEX `city_places_city_key_active_sort_order_idx`(`city_key`, `active`, `sort_order`),
    UNIQUE INDEX `city_places_city_key_name_ar_key`(`city_key`, `name_ar`),
    PRIMARY KEY (`id`),
    CONSTRAINT `city_places_latitude_range` CHECK (`latitude` BETWEEN -90 AND 90),
    CONSTRAINT `city_places_longitude_range` CHECK (`longitude` BETWEEN -180 AND 180)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE `passenger_requests`
    ADD COLUMN `pickup_place_id` VARCHAR(191) NULL,
    ADD COLUMN `pickup_place_name_ar` VARCHAR(160) NULL,
    ADD COLUMN `pickup_place_name_en` VARCHAR(160) NULL,
    ADD COLUMN `dropoff_place_id` VARCHAR(191) NULL,
    ADD COLUMN `dropoff_place_name_ar` VARCHAR(160) NULL,
    ADD COLUMN `dropoff_place_name_en` VARCHAR(160) NULL;

ALTER TABLE `merchant_orders`
    ADD COLUMN `pickup_place_id` VARCHAR(191) NULL,
    ADD COLUMN `pickup_place_name_ar` VARCHAR(160) NULL,
    ADD COLUMN `pickup_place_name_en` VARCHAR(160) NULL;

ALTER TABLE `parcels`
    ADD COLUMN `dropoff_place_id` VARCHAR(191) NULL,
    ADD COLUMN `dropoff_place_name_ar` VARCHAR(160) NULL,
    ADD COLUMN `dropoff_place_name_en` VARCHAR(160) NULL;

